def stamp2(r0,c0,n,flip_v=False,flip_h=False):
    for dr,dc,mh,mw,color in parts:
        if color==2: continue
        for ur in range(mh):
            for uc in range(mw):
                mr=-(dr+ur) if flip_v else dr+ur
                mc=-(dc+uc) if flip_h else dc+uc
                for y in range(r0+mr*n,r0+(mr+1)*n):
                    for x in range(c0+mc*n,c0+(mc+1)*n):
                        if 0<=y<N and 0<=x<N: out[y][x]=color
stamp2(4,19,3,flip_h=True)
stamp2(21,5,1,flip_v=True)
stamp2(19,18,4,flip_v=True,flip_h=True)
print('\n'.join(' '.join(map(str,row)) for row in out))
